/* SpryCollapsiblePanel.css - version 0.5 - Spry Pre-Release 1.6.1 */

/* Copyright (c) 2006. Adobe Systems Incorporated. All rights reserved. */

/* This is the selector for the main CollapsiblePanel container. For our
 * default style, the CollapsiblePanel is responsible for drawing the borders
 * around the widget.
 *
 * If you want to constrain the width of the CollapsiblePanel widget, set a width on
 * the CollapsiblePanel container. By default, our CollapsiblePanel expands horizontally to fill
 * up available space.
 *
 * The name of the class ("CollapsiblePanel") used in this selector is not necessary
 * to make the widget function. You can use any class name you want to style the
 * CollapsiblePanel container.
 */
.CollapsiblePanel {
	margin: 0px;
	padding: 0px;
	width:600px
}
/* This is the selector for the CollapsiblePanelTab. This container houses
 * the title for the panel. This is also the container that the user clicks
 * on to open or close the panel.
 *
 * The name of the class ("CollapsiblePanelTab") used in this selector is not necessary
 * to make the widget function. You can use any class name you want to style an
 * CollapsiblePanel panel tab container.
 */
.CollapsiblePanelTab {
	margin: 0px auto;
	padding: 10px 5px 10px 60px;
	cursor: pointer;
	-moz-user-select: none;
	-khtml-user-select: none;
	background:#f2f2f2;

}
/* This is the selector for a CollapsiblePanel's Content area. It's important to note that
 * you should never put any padding on the content area element if you plan to
 * use the CollapsiblePanel's open/close animations. Placing a non-zero padding on the content
 * element can cause the CollapsiblePanel to abruptly grow in height while the panels animate.
 *
 * The name of the class ("CollapsiblePanelContent") used in this selector is not necessary
 * to make the widget function. You can use any class name you want to style a
 * CollapsiblePanel content container.
 */

 .CollapsiblePanel {
	background:url(../images/nav/subBack.png) top left repeat-x;
	padding:1px 10px;
	margin-bottom:3px;
	color: #B32D2D;
	font-family: Georgia, "Times New Roman", Times, serif;
	font-size: 14px;
	font-weight:normal;
	/*border:2px solid #f1f1f2;*/
	*margin-bottom:1px;
	text-align:left;
}

.CollapsiblePanel p {
	padding:5px;
	line-height:25px;
	color: #333;
	font-family:Arial, Helvetica, sans-serif;
	background:#f1f1f2;
	font-size:13px;
	font-weight:normal;

}

.CollapsiblePanel p.title{
	color: #345baf;
	font-family: Arial,Helvetica,sans-serif;
	background:#f1f1f2;
	font-size:13px;
	font-weight:bold;
	padding:5px;
}

#journal {
	font-family: Arial,Helvetica,sans-serif;
	background:#f1f1f2;
	padding:5px;
}

#journal h5{
	color: #5b9400;
	font-family:"Times New Roman", Times, serif;
	font-size:15px;
	font-weight:bold;
	margin:0;
	padding:0;
	padding-bottom:5px;
	padding-top:8px;
	text-decoration:underline;
}
#journal p{
	color: #666;
	font-size:13px;
	font-weight:normal;
	margin:0;
	padding:0;

}

.CollapsiblePanelContent {
	margin: 0px;
	padding: 0px;
}
.CollapsiblePanelTab a {
	color: #ffffff;
	font-weight:bold;
	text-decoration: none;
	font-size:14px
}
.CollapsiblePanelTab:hover a:link, .CollapsiblePanelTab:focus a:link {
	color: #ffffff;
	font-weight:bold;
	text-decoration: none;
	font-size:14px
}
.CollapsiblePanelTab {
	background:url(../images/nav/open.gif) right no-repeat;
	color:#9c0052;
	font-size:14px;
	font-family:Arial, Helvetica, sans-serif;
}
.CollapsiblePanelTab {
}
/* This is an example of how to change the appearance of the panel tab that is
 * currently open. The class "CollapsiblePanelOpen" is programatically added and removed
 * from panels as the user clicks on the tabs within the CollapsiblePanel.
 */
.CollapsiblePanelOpen {
	/*-webkit-box-shadow: 0px 0px 4px #7d879b;
	-moz-box-shadow: 0px 0px 4px #7d879b;*/
*border:2px solid #dedfe2;
color:#9c0052;

}
/* This is an example of how to change the appearance of the panel tab when the
 * CollapsiblePanel is closed. The "CollapsiblePanelClosed" class is programatically added and removed
 * whenever the CollapsiblePanel is closed.
 */

.CollapsiblePanelClosed .CollapsiblePanelTab {
	background:#F2F2F2 url(../images/nav/open.png) left no-repeat;
}

.CollapsiblePanelClosed .CollapsiblePanelTab a, .CollapsiblePanelClosed .CollapsiblePanelTab:hover a {
	color:#333;
	font-weight:400;
}
.CollapsiblePanelTabOpen, .CollapsiblePanelTab {
	background:#2c6c9a url(../images/nav/close.png) left no-repeat;
}
/* This is an example of how to change the appearance of all the panel tabs when the
 * CollapsiblePanel has focus. The "CollapsiblePanelFocused" class is programatically added and removed
 * whenever the CollapsiblePanel gains or loses keyboard focus.
 */
.CollapsiblePanelFocused  { color: #fff;
}

