.search_widget_div {
    background-color: #cccccc;
    border-radius: 5px;
    left: 10%;
    overflow: hidden;
    position: absolute;
    top: 0px;
    width: 200px;
    z-index: 9999;
}

.search_widget_div_level1{
	width:100%;
	height:29px;
	background-color: #e8e8e8;
	overflow: hidden;
	-webkit-border-radius: 5px;
	-moz-border-radius: 5px;
	border-radius: 5px;
}
.search_widget_textfield{
	border: none;
	height:30px;
	text-indent: 5px;
	background-color: #e8e8e8;
	width: 154px;
	margin: 0px;padding:0px; 
	font: 9pt "leelawad";
	font-weight: normal;
	color: #676464;
}
.search_widget_btn{
	border: none;
	height:30px;
	width:42px;
	background:#ec550a url(../images/searchico.png) no-repeat 50% center;
}
.search_widget_btn:hover{
	background-color: #ff6000;
}
.search_widget_div_level2{
	width:100%;
	margin-top: 5px;
	margin-bottom: 5px;
	display: none;
}
.search_widget_label{
	margin: 2px;
	font: 10pt "leelawad";
	font-weight: normal;
	color: #676464;
}
